let randInt = (a, b) => (floor(random(a, b))); 

function setup() {
  createCanvas(500, 500);
  pixelDensity(4);
	noStroke();
	noLoop();
}

function draw() {
	let myWhite = "#fffbe6", myBlack = "#050505", accentCol = "#b3dce0";
	background(myWhite);
	let palette = [[myWhite, accentCol], ["#62b6de", accentCol], [myBlack, accentCol]];
	let colOffset = randInt(0, 3);

	translate(width/2, height/2);
	for (let i = 0; i < 3; i++) {
		push();
		rotate(i*TAU/3 + PI/6);
		shearX(-PI/6);
		//scale(1, sqrt(1-sq(PI/6)));
		scale(1, 0.865);
		recursiveRectPacking(7, palette[(i+colOffset)%3]);
		pop();
	}

}

// everything combined

function recursiveRectPacking(M, colors) {
	let u = width/M;
	u *= 0.33;
	let gap = u/8;

	let iMin = 0, iMax = M, jMin = 0, jMax = M;
	let siMax = ~~(M/2);
	let sjMax = ~~(M/2);
	let rectangles = createComposition(iMin, iMax, jMin, jMax, siMax, sjMax, 0, colors, 500);

	fill(colors[1]);
	square(0, 0, M*u+gap/2);

  for (let recta of rectangles) {
		drawRectangle(recta, u, gap);

		let iMin1 = 4*recta.i;
		let iMax1 = 4*(recta.i+recta.si) - 1;
		let jMin1 = 4*recta.j;
		let jMax1 = 4*(recta.j+recta.sj) - 1;
		let siMax1 = round(4*recta.si/2);
		let sjMax1 = round(4*recta.sj/2);
		createSubcompo(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, u, gap, 1, colors, 500);
	}
}


// creating the composition

function createComposition(iMin, iMax, jMin, jMax, siMax, sjMax, depth, colors, nAttempts) {
	let rectangles = [];

	for (let i = 0; i < nAttempts; i++) {
    let newRecta = generateRectangle(rectangles, iMin, iMax, jMin, jMax, siMax, sjMax, depth, colors);
    if (((newRecta.si > 1 || newRecta.sj > 1) && random() < 1/2) || (newRecta.si > 1 && newRecta.sj > 1)) { // no 1x1 squares and avoid thin rectangles
      rectangles.push(newRecta);
    }
  }

  // fill the gaps with 1x1 rectangles
	for (let i = iMin; i < iMax; i++) {
		for (let j = jMin; j < jMax; j++) {
			let newRecta = {
				i: i,
				j: j,
				si: 1,
				sj: 1,
				col: colors[depth%colors.length]
			}
			let canAdd = true;
			for (let recta of rectangles) {
				if (rectanglesIntersect(newRecta, recta)) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				rectangles.push(newRecta);
			}
		}
	}

	return rectangles;
}

function rectanglesIntersect(recta1, recta2) {
	return ((recta1.i <= recta2.i && recta1.i+recta1.si > recta2.i) || (recta2.i <= recta1.i && recta2.i+recta2.si > recta1.i)) && ((recta1.j <= recta2.j && recta1.j+recta1.sj > recta2.j) || (recta2.j <= recta1.j && recta2.j+recta2.sj > recta1.j));
}

function generateRectangle(rectangles, iMin, iMax, jMin, jMax, siMax, sjMax, depth, colors) {
  let i = randInt(iMin, iMax);
  let j = randInt(jMin, jMax);

	// determine biggest possible size
	let si, sj;
	if (rectangles.length == 0) {
		si = min(siMax, iMax-i);
		sj = min(sjMax, jMax-j);
	} else {
		let si1 = biggestPossibleWidth(rectangles, iMax, siMax, i, j, 1, 1);
		let sj1 = biggestPossibleHeight(rectangles, jMax, sjMax, i, j, si1, 1);

		let sj2 = biggestPossibleHeight(rectangles, jMax, sjMax, i, j, 1, 1);
		let si2 = biggestPossibleWidth(rectangles, iMax, siMax, i, j, 1, sj2);

		if (si1*sj1 > si2*sj2) {
			si = si1;
			sj = sj1;
		} else {
			si = si2;
			sj = sj2;
		}
	}

	if (random() < 1/2) { // avoid squares
		if (si == sj && si > 1) {
			if (random() < 1/2) {
				si--;
			} else {
				sj--;
			}
		}
	}

  let recta = {
    i: i,
    j: j,
    si: si,
		sj: sj,
		col: colors[depth%colors.length]
  };
  return recta;
}

function biggestPossibleWidth(rectangles, iMax, siMax, i, j, si, sj) {
	let s = si;
	let intersects = false;
	while (!intersects) {
		s++;
		for (let recta of rectangles) {
			if (i+s > iMax || s > siMax || rectanglesIntersect({i: i, j: j, si: s, sj: sj}, recta)) {
				intersects = true;
				break;
			}
		}
	}
	return s-1;
}

function biggestPossibleHeight(rectangles, jMax, sjMax, i, j, si, sj) {
	let s = sj;
	intersects = false;
	while (!intersects) {
		s++;
		for (let recta of rectangles) {
			if (j+s > jMax || s > sjMax || rectanglesIntersect({i: i, j: j, si: si, sj: s}, recta)) {
				intersects = true;
				break;
			}
		}
	}
	return s-1;
}

// recursive part

function createSubcompo(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, u, gap, depth, colors, nAttempts) {
	let subrectangles = createComposition(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, depth, colors, nAttempts);
	for (let subrecta of subrectangles) {
		push();
		translate(u/8, u/8);
		drawRectangle(subrecta, u/4, gap);
		if (subrecta.si > 1 && subrecta.sj > 1) {
			let iMin2 = subrecta.i;
			let iMax2 = iMin2 + subrecta.si - 1;
			let jMin2 = subrecta.j;
			let jMax2 = jMin2 + subrecta.sj - 1;
			let siMax2 = round(subrecta.si/2);
			let sjMax2 = round(subrecta.sj/2);
			createSubcompo(iMin2, iMax2, jMin2, jMax2, siMax2, sjMax2, u, gap, depth+1, colors, nAttempts);
		}
		pop();
	}
}

// drawing

function drawRectangle(recta, s, gap) {
	let x = recta.i*s + gap/2, y = recta.j*s + gap/2;
	let w = recta.si*s - gap, h = recta.sj*s - gap;
	fill(recta.col);
	rect(x, y, w, h);
}

